package com.nexadesk.ai;

/** Where an answer comes from. Every AI response carries it, and the UI shows it as a badge. */
public enum AiSource {
    /** Generated by the connected language model. */
    LLM,
    /** Computed locally by rules and PostgreSQL search: no model involved. */
    HEURISTIC,
    /** AI features turned off by configuration. */
    DISABLED
}
